/** How far the Net worth projection runs: 10, 20 or 30 years, or to 65. */
export type Horizon = "10y" | "20y" | "30y" | "65";

/** Whether the Net worth projection is in today's dollars or future ones. */
export type Dollars = "today" | "future";

/**
 * G14: one income row as the Net worth page edits it, however old the
 * stored row: `to` null runs to the horizon; `bonus_months` is months of pay
 * as text ("1.5") and `bonus_month` the month of the year it lands in, both
 * null for a side income row or a job with no bonus.
 */
export type IncomeRow = {
  name: string;
  type: IncomeType;
  from: string;
  to: string | null;
  gross_minor: Cents;
  cpf: boolean;
  bonus_months: string | number | null;
  bonus_month: number | null;
};

/**
 * G14: the monthly transfer to investments from a month (YYYY-MM) on;
 * `from` null is from the start.
 */
export type InvestingStep = {
  from: string | null;
  amount_minor: Cents;
};

/**
 * G14: the Net worth projection's saved settings with the defaults filled
 * in. Rates are per cent a year as text ("6.5"); `spend_growth_pct` null
 * follows inflation; `spend_minor` null is the record's own average and
 * `milestone_minor` null is no milestone.
 */
export type ProjectionSettings = {
  pessimistic_pct: string;
  expected_pct: string;
  optimistic_pct: string;
  inflation_pct: string;
  salary_growth_pct: string;
  sums_growth_pct: string;
  spend_growth_pct: string | null;
  horizon: Horizon;
  dollars: Dollars;
  spend_minor: Cents | null;
  milestone_minor: Cents | null;
};

/**
 * The Net worth page's inputs, as GET /api/growth answers them under
 * `inputs` and POST /api/growth/preview and /api/growth/inputs take them.
 */
export type GrowthInputs = {
  income: IncomeRow[];
  investing: InvestingStep[];
  projection: ProjectionSettings;
};

/**
 * An income row as the plan stores it. A segment from before G14 has a
 * `note` and no name, type or CPF; GET /api/growth's IncomeRow is the same
 * row with those filled in.
 */
export type PlanIncomeRow = {
  name?: string;
  type?: IncomeType;
  from: string;
  to?: string | null;
  gross_minor: Cents;
  cpf?: boolean;
  note?: string;
  bonus_months?: string | number;
  bonus_month?: number;
};

/**
 * A planned trip the forward view costs: spending a day (left out for
 * the record's own rate on past trips) and flights in `flights_month`, its
 * first month unless set.
 */
export type PlanTrip = {
  name?: string;
  from: string;
  to: string;
  per_day_minor?: Cents;
  flights_minor?: Cents;
  flights_month?: string;
  note?: string;
};

/** A one-off payment in a month. */
export type PlanOneOff = {
  month: string;
  amount_minor: Cents;
  label?: string;
};

/**
 * The projection settings as the plan stores them: only what was typed.
 * GET /api/growth answers them with the defaults filled in.
 */
export type PlanProjection = {
  pessimistic_pct?: string;
  expected_pct?: string;
  optimistic_pct?: string;
  inflation_pct?: string;
  salary_growth_pct?: string;
  sums_growth_pct?: string;
  spend_growth_pct?: string;
  horizon?: Horizon;
  dollars?: Dollars;
  spend_minor?: Cents;
  milestone_minor?: Cents;
};

/**
 * The plan, every key optional. `to` is the forward view's last month;
 * `cpf_employer_rate` is a fraction (0.17), not money; `dca_minor` is the
 * single investing transfer from before G14's investing steps. The money
 * sits in cents under the `_minor` names; POST /api/plan takes the same
 * shape (and, for one release, dollars under the bare names).
 */
export type Plan = {
  to?: string;
  dca_minor?: Cents | null;
  insurance_minor?: Cents | null;
  other_income_minor?: Cents | null;
  repayments_minor?: Cents | null;
  cpf_employer_rate?: number;
  spend_rate?: string;
  spend_exclude_keys?: string[];
  income?: PlanIncomeRow[];
  investing?: InvestingStep[];
  trips?: PlanTrip[];
  one_offs?: PlanOneOff[];
  projection?: PlanProjection;
};

/**
 * GET /api/plan: the plan, the categories, the need classes and the
 * forward view's spending rates.
 */
export type PlanState = {
  plan: Plan;
  categories: Category[];
  need_classes: NeedClass[];
  spend_rates: string[];
};

/** G22: a provider server/finance/ai.py knows (ai.PROVIDERS). */
export type AiProvider = "anthropic" | "openai" | "xai" | "gemini" | "deepseek" | "qwen" | "moonshot" | "zhipu" | "zai" | "mistral" | "groq" | "together" | "fireworks" | "cerebras" | "openrouter" | "ollama";

/**
 * G22: where the provider's API key was found. `keychain` and `env_file` are
 * the two places Settings saves one; `none` when there is no key.
 */
export type KeyPlace = "keychain" | "env_file" | "environment" | "key_file" | "key_command" | "none";

/** G22: one provider the AI card offers. */
export type AiProviderInfo = {
  name: AiProvider;
  label: string;
  /** True for a provider on this machine (Ollama): no key, and nothing leaves the machine. */
  local: boolean;
  /** The model used when none is picked; "" when the provider has no stable default. */
  default_model: string;
  /** The Ask Kopifund model used when none is picked; "" to use the payee suggestions model. */
  copilot_default_model: string;
};

/** G22: the provider's API key as the page may see it: never the key. */
export type AiKey = {
  where: KeyPlace;
  /** The key's last four characters, or null when there is no key. */
  last4: string | null;
  /** True when Settings saved it (keychain or env_file), so Remove can take it out. */
  can_remove: boolean;
};

/** GET /api/ai: the AI card on Settings. */
export type AiSettings = {
  /** True when a provider is picked (Settings or [ai] in config.toml) and AI is not turned off in Settings. */
  enabled: boolean;
  /** A name from `providers`, or a custom provider config.toml names (with its base_url); null when none. */
  provider: string | null;
  providers: AiProviderInfo[];
  /** The payee suggestions model; "" for the provider's default. */
  model: string;
  /** The Ask Kopifund model; "" to use `model`. */
  copilot_model: string;
  /** G22: the payee suggestions model requests really use (a saved choice, [ai] in config.toml, or the provider's default); "" when there is none. */
  model_in_use: string;
  /** G22: the Ask Kopifund model requests really use; "" when there is none, so the copilot cannot run. */
  copilot_model_in_use: string;
  key: AiKey;
  /** The copilot consent switch (`copilot.send_rows` in the setting table). */
  send_rows: boolean;
  /** True when the provider runs on this machine, so the copilot needs no consent. */
  local: boolean;
  /** True when the provider comes from [ai] in config.toml rather than Settings. */
  from_config: boolean;
  /** G22: the provider [ai] in config.toml names, built-in or custom (with its base_url), even when Settings has picked another or turned AI off; null when config.toml names none. Saving it as `provider` clears Settings' choice so config.toml decides again; a custom one's model is set only in config.toml. */
  config_provider: string | null;
};

/** G22: one model a provider lists. */
export type AiModel = {
  id: string;
  label: string;
};

/** GET /api/ai/models?provider=&q=: the provider's models matching q, from a day-old cache at most. */
export type AiModels = {
  provider: AiProvider;
  models: AiModel[];
  /** When the server last fetched the provider's list (ISO time), or null when it could not. */
  fetched_at: string | null;
  /** Why the list could not be fetched (no key, the provider refused); the field still takes typing. */
  error: string | null;
};

/** POST /api/ai/test: whether the provider answered one short request. */
export type AiTest = {
  ok: boolean;
  message: string;
  ms: number | null;
};

/** G22: the page a question was asked on, and its filters. */
export type CopilotPage = {
  path: string;
  title: string;
  filters: Record<string, string>;
};

/** G22: one tool the copilot ran, as the quiet line the panel shows. */
export type CopilotTool = {
  name: string;
  label: string;
};

/** G22: a link into the app, e.g. Transactions for exactly the rows a figure counted. */
export type CopilotLink = {
  label: string;
  href: string;
};

/** G22: a chart in the stats' chart hint shape (server/analytics/SPEC.md, "The chart hint"). */
export type CopilotChart = {
  title: string;
  chart: Record<string, unknown>;
};

/** G22: what a confirm card would change. */
export type CardKind = "rule" | "category" | "budget" | "trip";

/** G22: a write the page sends on Confirm (or Undo) to an existing endpoint. */
export type CopilotRequest = {
  path: string;
  body: Record<string, unknown>;
};

/** G22: a change the model suggests; nothing is saved until the owner presses Confirm. */
export type CopilotCard = {
  id: string;
  kind: CardKind;
  title: string;
  summary: string;
  /** Lines the card shows under its summary (for a rule, the rows it would change). */
  preview: string[];
  request: CopilotRequest;
  /** The write that puts things back; null when the endpoint's own answer carries its Undo, or (a budget) when the page reads the amount to put back at Confirm. */
  undo: CopilotRequest | null;
};

/** G22: one step of an answer: the model's summarized thinking for a round, the tools one round ran, or the text a round wrote before calling tools. */
export type CopilotStepKind = "thinking" | "tools" | "text";

/** G22: one step of an answer, shown in order above the final answer, collapsed. */
export type CopilotStep = {
  kind: CopilotStepKind;
  /** The thinking summary or the interim text; "" for a tools step. */
  text: string;
  /** The tools one round ran; [] for a thinking or text step. */
  tools: CopilotTool[];
};

/** G22: one turn of a thread. */
export type CopilotMessage = {
  role: "user" | "assistant";
  /** For an answer, the final answer; the text written between rounds is in `steps`. */
  text: string;
  at: string;
  page: CopilotPage | null;
  tools: CopilotTool[];
  /** The answer's steps in order ([] for a question). A thread saved before steps existed loads with []; the panel then shows `tools` as one tools step. */
  steps: CopilotStep[];
  charts: CopilotChart[];
  links: CopilotLink[];
  cards: CopilotCard[];
  /** Short questions the panel offers as chips under the answer. */
  followups: string[];
};

/** G22: a thread in the panel's list. */
export type CopilotThreadOutline = {
  id: string;
  title: string;
  updated_at: string;
  turns: number;
};

/** GET /api/copilot/threads: newest first. */
export type CopilotThreads = {
  threads: CopilotThreadOutline[];
};

/** GET /api/copilot/threads/<id>. */
export type CopilotThread = {
  id: string;
  title: string;
  updated_at: string;
  messages: CopilotMessage[];
};

/** G22: one line of POST /api/copilot/ask's answer. */
export type CopilotEventType = "thread" | "thinking" | "tool" | "say" | "text" | "chart" | "link" | "card" | "followups" | "error" | "done";

/** G22: one line of JSON in POST /api/copilot/ask's answer, sent as it happens. */
export type CopilotEvent = {
  type: CopilotEventType;
  thread?: CopilotThreadOutline;
  tool?: CopilotTool;
  /** For `thinking`: a round's thinking summary; for `say`: the text a round wrote before calling tools; for `text`: the final answer. */
  text?: string;
  chart?: CopilotChart;
  link?: CopilotLink;
  card?: CopilotCard;
  followups?: string[];
  /** For `error`: what went wrong, in the app's words. */
  message?: string;
};

/**
 * One paired phone (server/finance/link.py). The bearer never leaves the
 * registry: only its hash is kept, and nothing of either is sent.
 */
export type LinkDevice = {
  id: string;
  name: string;
  paired_at: string;
  revoked: boolean;
};

/**
 * GET /api/link/devices: the paired phones, and the tailnet URL the
 * pair QR carries ("" when tailscale cannot say).
 */
export type LinkDevices = {
  devices: LinkDevice[];
  url: string;
};

/** POST /api/link/pair-token: the QR payload and what it encodes. */
export type PairToken = {
  payload: string;
  url: string;
  expires_in: number;
};

/** POST /api/pair/redeem: the credentials the phone keeps. */
export type PairedDevice = {
  device_id: string;
  name: string;
  token: string;
};

/**
 * G25: where a phone row stands: waiting for its statement row, matched to
 * it, or dismissed as no spend.
 */
export type PendingState = "waiting" | "matched" | "dismissed";

/**
 * G25: one spend the phone told the record about (server/finance/pending.py).
 * `amount_minor` is signed the ledger's way: spending negative.
 */
export type PendingRow = {
  import_id: string;
  device_id: string;
  /** The paired phone's name, "" when its registry row is gone. */
  device: string;
  date: string;
  amount_minor: Cents;
  currency: string;
  payee: string;
  state: PendingState;
  matched_txn_key: string | null;
};

/** GET /api/link/pending: every pending row, waiting first. */
export type LinkPending = {
  rows: PendingRow[];
};

/**
 * POST /api/link/transactions: how many of the rows sent were new or
 * corrected, and how many waiting rows a confirm matched after them.
 */
export type LinkPosted = {
  accepted: number;
  matched: number;
};

/** One icon set in app-icons/sets.json; its files are under /app-icons/<name>/. */
export type AppIconSet = {
  name: string;
  label: string;
  /** a few words on what it shows */
  about: string;
};

/**
 * GET and POST /api/app-icon: the icon sets in picker order, the one the
 * apps open with, and the one picked in Settings (finance/app_icon.py).
 */
export type AppIconPage = {
  sets: AppIconSet[];
  default: string;
  chosen: string;
};

/**
 * G23: how the running server was started: `make serve`, `make dev` (`--page` is
 * set only there), or the desktop app's sidecar.
 */
export type ServerMode = "serve" | "dev" | "app";

/**
 * GET /api/server: the running server, for Settings' Server card. `started`
 * is the process's own start in epoch seconds, so the card's "running for"
 * resets on a restart.
 */
export type ServerInfo = {
  version: string;
  mode: ServerMode;
  port: number;
  pid: number;
  started: number;
};

/**
 * The data source a widget query reads: `spending` is the record's own rows;
 * the others are the cached stat results and net_worth.py's combination of them
 * (server/finance/dashboard.py, _CATALOGUE).
 */
export type WidgetSource = "spending" | "monthly-cashflow" | "needs-wants-savings" | "savings-runway" | "category-breakdown" | "portfolio" | "cpf" | "net-worth" | "forward-view";

/**
 * What a widget query spreads its metric over. A source keeps its own list
 * (`month` for a series, `bucket`/`category`/`payee`/`account`/`need` for the
 * spending splits, `part`/`year`/`period`/`holding` for the stat sources).
 */
export type WidgetDimension = "month" | "bucket" | "category" | "payee" | "account" | "need" | "part" | "year" | "period" | "holding";

/**
 * The unit a resolved series is in. `sgd_minor` is integer cents, `months` a
 * runway, `fraction` a ratio the app multiplies by 100, `percent` already scaled.
 */
export type WidgetUnit = "sgd_minor" | "months" | "fraction" | "percent";

export type WidgetRange = {
  from?: string;
  to?: string;
};

/**
 * What a widget asks: one source, one metric, the dimension to spread it
 * over. `split` (a spending query by month) makes one series per name;
 * `filters` are Transactions' own filter names (server/finance/dashboard.py).
 */
export type WidgetQuery = {
  source: WidgetSource;
  metric: string;
  dimension?: WidgetDimension;
  range?: WidgetRange;
  split?: string;
  filters?: Record<string, string>;
};

/**
 * One series of an answer: money under `values_minor` (integer cents),
 * anything else under `values`; `link` is the Transactions filter the
 * series lists (the G13 chart.links idea).
 */
export type WidgetSeries = {
  name: string;
  values_minor?: (Cents | null)[];
  values?: (number | null)[];
  link?: Record<string, string> | null;
};

/**
 * GET or POST /api/dashboard/query: a query resolved to labels and
 * series. `label_links` (aligned to `labels`) is the Transactions filter a
 * point lists; `note` marks an estimate (a projection source or a preview).
 */
export type WidgetAnswer = {
  source: WidgetSource;
  metric: string;
  dimension: string;
  range: WidgetRange | null;
  unit: WidgetUnit;
  labels: string[];
  label_links?: (Record<string, string> | null)[];
  series: WidgetSeries[];
  note?: string;
};

/**
 * POST /api/dashboard/scenario/preview: the query's series drawn ahead on
 * its trailing monthly average. Nothing is written.
 */
export type ScenarioPreview = WidgetAnswer & {
  /** The index in `labels` where the projection starts. */
  projected_from: number;
};

/**
 * One widget on a layout: an id, its kind (`kpi`, `line`, `pie`, ...), an
 * optional bound `query` and a `layout` grid cell ({x, y, w, h}).
 */
export type DashboardWidget = {
  id: string;
  type: string;
  title?: string;
  query?: WidgetQuery;
  layout?: Record<string, number>;
  options?: Record<string, unknown>;
};

/** One named layout: its widgets and when it was last written. */
export type DashboardLayout = {
  id: string;
  name: string;
  widgets: DashboardWidget[];
  updated_at: string;
};

/** GET /api/dashboard/layouts: every layout and the active one's id. */
export type DashboardLayouts = {
  layouts: DashboardLayout[];
  active: string | null;
};

/** A goal's dated checkpoint. */
export type DashboardMilestone = {
  month: string;
  target_minor: Cents;
};

/**
 * A goal's progress binding: the widget query (a money metric) whose last
 * figure is the goal's `current_minor`.
 */
export type GoalBinding = {
  source: WidgetSource;
  metric: string;
  dimension: string;
};

/**
 * One goal: its target in cents, optional target month, milestones, and
 * the progress its binding resolves to (`current_minor`, `progress` as a
 * fraction of target; null when it has none).
 */
export type DashboardGoal = {
  id: string;
  name: string;
  target_minor: Cents;
  month: string | null;
  note: string;
  milestones: DashboardMilestone[];
  binding?: GoalBinding;
  current_minor: Cents | null;
  progress: number | null;
};

/** GET /api/dashboard/goals. */
export type DashboardGoals = {
  goals: DashboardGoal[];
};

/**
 * A spend bucket in a month: its planned cents from the template (null
 * while unplanned), the month's actual spend, and `share` of the month's
 * income (a fraction; null when income is 0).
 */
export type AllocationBucket = {
  bucket: string;
  planned_minor: Cents | null;
  actual_minor: Cents;
  share: number | null;
};

/** One template row: a spend bucket's planned cents a month. */
export type AllocationTemplate = {
  bucket: string;
  planned_minor: Cents;
};

/**
 * GET /api/dashboard/allocation?month=: the template beside a month's
 * actuals. `unallocated_minor` is income less every planned amount (null
 * until a template exists and the month has income); `month` is null
 * before the first load.
 */
export type Allocation = {
  month: string | null;
  months: string[];
  income_minor: Cents;
  template: AllocationTemplate[];
  buckets: AllocationBucket[];
  unallocated_minor: Cents | null;
};

/** An account the game pot may link. */
export type GamePotAccount = {
  id: number;
  name: string;
};

/**
 * GET /api/dashboard/game-pot: the pot's settings, `on` once any are
 * saved, and `accounts` the record holds (each an id it may link).
 */
export type GamePot = {
  name: string;
  benchmark: string;
  note: string;
  account_ids: number[];
  accounts: GamePotAccount[];
  on: boolean;
};

