export const CACHED_PATHS: readonly string[] = [
  "/api/budgets",
  "/api/categories",
  "/api/dashboard/allocation",
  "/api/dashboard/game-pot",
  "/api/dashboard/goals",
  "/api/dashboard/layouts",
  "/api/dashboard/query",
  "/api/growth",
  "/api/net-worth",
  "/api/overview",
  "/api/plan",
  "/api/profile",
  "/api/recurring",
  "/api/recurring/series",
  "/api/rules",
  "/api/rules/rows",
  "/api/scam-checks",
  "/api/spending",
  "/api/suggestions",
  "/api/transactions",
  "/api/trips",
];

/** serve.py, CACHED_PREFIX: every stat's own result is cached too. */
export const CACHED_PREFIX = "/api/results/";

/** serve.py, NO_CHANGE: the writes that change nothing a GET reads, so no view reloads after them. */
export const NO_CHANGE_PATHS: readonly string[] = [
  "/api/ai/test",
  "/api/copilot/ask",
  "/api/copilot/threads/remove",
  "/api/dashboard/query",
  "/api/dashboard/scenario/preview",
  "/api/growth/preview",
  "/api/link/devices/revoke",
  "/api/link/pair-token",
  "/api/pair/redeem",
  "/api/rules/suggest",
  "/api/run/check",
  "/api/server/restart",
  "/api/server/stop",
  "/api/uploads/start",
];

/** serve.py, REREAD_AFTER (G18): after one of these writes, the GETs a view asks for again; nothing else kept is forgotten. */
export const REREAD_AFTER: Readonly<Record<string, readonly string[]>> = {
  "/api/dashboard/allocation": ["/api/dashboard/allocation"],
  "/api/dashboard/game-pot": ["/api/dashboard/game-pot"],
  "/api/dashboard/goals": ["/api/dashboard/goals"],
  "/api/dashboard/goals/remove": ["/api/dashboard/goals"],
  "/api/dashboard/layouts": ["/api/dashboard/layouts"],
  "/api/dashboard/layouts/<id>": ["/api/dashboard/layouts"],
  "/api/run/check": ["/api/overview"],
};
